package cn.zhuatech.fsm.controller; import cn.zhuatech.fsm.common.ApiResponse; import cn.zhuatech.fsm.dto.FsmDto.*; import cn.zhuatech.fsm.service.FsmService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('SERVICE_DISPATCHER','QUALITY','ADMIN')") public class FieldServiceAdminController {private final FsmService service;public FieldServiceAdminController(FsmService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkOrderView>> orders(){return ApiResponse.ok(service.workOrders());}}
